using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Xunit;
namespace BuildingFlow.IntegrationTests;

public sealed class CentralPeopleTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>,IDisposable {
 private WebApplicationFactory<Program>? enabled;
 private const string Issuer="http://localhost:8080/realms/buildingflow";
 private static string Root(Guid t)=>$"/api/v2/tenants/{t}/people";
 private static CentralPersonProfile Profile(string first="Fixture")=>new("NATURAL","DOMESTIC","TR","12345678901",first,"Example",null,null,"+905551234567","fixture@example.test");
 private HttpClient Client(string? user,string role,bool feature=true){
  enabled??=factory.WithWebHostBuilder(b=>b.ConfigureAppConfiguration((_,c)=>c.AddInMemoryCollection(new Dictionary<string,string?>{{"PersonRefactor:Enabled","true"}})));
  var c=(feature?enabled:factory).CreateClient();using var signed=TestToken.Client(factory,user,role);c.DefaultRequestHeaders.Authorization=signed.DefaultRequestHeaders.Authorization;return c;
 }
 private async Task<(Guid Tenant,string User,Guid Account,Guid Member)> Seed(string? subject=null,string issuer=Issuer){
  var t=new PersonTenant("Fixture tenant");var user=subject??Guid.NewGuid().ToString();var a=new PersonUserAccount(issuer,user);var m=new PersonTenantMembership(t.Id,a.Id);
  await factory.WithDb(async db=>{db.AddRange(t,a,m);await db.SaveChangesAsync();});return(t.Id,user,a.Id,m.Id);
 }
 private static async Task<CentralPersonMutation> Value(HttpResponseMessage r){Assert.Equal(HttpStatusCode.OK,r.StatusCode);return(await r.Content.ReadFromJsonAsync<CentralPersonMutation>())!;}
 private Task<HttpResponseMessage> Create(HttpClient c,Guid t,Guid? op=null,CentralPersonProfile? p=null)=>c.PostAsJsonAsync(Root(t),new CreateCentralPersonRequest(op??Guid.NewGuid(),p??Profile()));
 [PostgresFact]public async Task FeatureDefaultsOffAndLegacyPeopleRemainUnchanged(){var s=await Seed();using var c=Client(s.User,"MANAGER",false);Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync(Root(s.Tenant))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Create(c,s.Tenant)).StatusCode);await factory.WithDb(async db=>Assert.False(await db.Set<CentralPerson>().AnyAsync(p=>p.TenantId==s.Tenant)));}
 [PostgresFact]public async Task ManagersCrudWithoutAnyPropertyAndSharedContactOrIdentityNeverAutoMerges(){var s=await Seed();using var c=Client(s.User,"MANAGER");var one=await Value(await Create(c,s.Tenant));var two=await Value(await Create(c,s.Tenant));Assert.NotEqual(one.Record.Id,two.Record.Id);Assert.Equal(s.Tenant,one.Record.TenantId);Assert.Equal(1,one.Record.Version);
  var update=new UpdateCentralPersonRequest(Guid.NewGuid(),one.Record.Version,Profile("Changed"),true);var changed=await Value(await c.PutAsJsonAsync(Root(s.Tenant)+"/"+one.Record.Id,update));Assert.Equal(2,changed.Record.Version);Assert.Equal("Changed",changed.Record.Profile.FirstName);
  var dto=(await c.GetFromJsonAsync<CentralPersonDetail>(Root(s.Tenant)+"/"+one.Record.Id))!;Assert.Equal(changed.Record,dto);Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync(Root(s.Tenant)+"/"+one.Record.Id,update with{OperationId=Guid.NewGuid()})).StatusCode);
  await factory.WithDb(async db=>{Assert.Equal(2,await db.Set<CentralPerson>().CountAsync(p=>p.TenantId==s.Tenant));var saved=await db.Set<CentralPerson>().SingleAsync(p=>p.Id==one.Record.Id);Assert.Equal(s.User,saved.CreatedBy);Assert.Equal(s.User,saved.ModifiedBy);Assert.Equal(one.Record.CreatedAt,saved.CreatedAt);});
 }
 [PostgresFact]public async Task SameUuidConcurrentCreateAndReplayAfterUpdateReturnOneOperationAndCurrentRecord(){var s=await Seed();using var c=Client(s.User,"MANAGER");var op=Guid.NewGuid();var results=await Task.WhenAll(Create(c,s.Tenant,op),Create(c,s.Tenant,op));var values=await Task.WhenAll(results.Select(Value));Assert.Single(values,v=>v.Replayed);Assert.Equal(values[0].Record.Id,values[1].Record.Id);var id=values[0].Record.Id;
  var changed=await Value(await c.PutAsJsonAsync(Root(s.Tenant)+"/"+id,new UpdateCentralPersonRequest(Guid.NewGuid(),1,Profile("Updated"),true)));var replay=await Value(await Create(c,s.Tenant,op));Assert.True(replay.Replayed);Assert.Equal(changed.Record.Version,replay.Record.Version);Assert.Equal(1,replay.AppliedVersion);Assert.Equal(HttpStatusCode.Conflict,(await Create(c,s.Tenant,op,Profile("Different"))).StatusCode);
  await factory.WithDb(async db=>{Assert.Equal(2,await db.Set<CentralPersonOperation>().CountAsync(o=>o.TenantId==s.Tenant));await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE person_operation_receipts SET fingerprint='changed' WHERE tenant_id={s.Tenant}"));});
 }
 [PostgresFact]public async Task SameVersionConcurrentUpdatesAllowOnlyOneAndNoopStillIncrementsVersion(){var s=await Seed();using var c=Client(s.User,"MANAGER");var d=await Value(await Create(c,s.Tenant));var cmd=new UpdateCentralPersonRequest(Guid.NewGuid(),1,Profile(),true);var responses=await Task.WhenAll(c.PutAsJsonAsync(Root(s.Tenant)+"/"+d.Record.Id,cmd),c.PutAsJsonAsync(Root(s.Tenant)+"/"+d.Record.Id,cmd with{OperationId=Guid.NewGuid(),Profile=Profile("Changed")}));Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Equal(2,(await Value(responses.Single(x=>x.StatusCode==HttpStatusCode.OK))).Record.Version);}
 [PostgresTheory][InlineData("RESIDENT")][InlineData("OWNER")][InlineData("TENANT")][InlineData("ACCOUNTANT")][InlineData("spoofed")][InlineData("client-role")]
 public async Task NonManagersCannotListReadOrWritePeople(string role){var s=await Seed();using var admin=Client(s.User,"MANAGER");var p=await Value(await Create(admin,s.Tenant));using var c=Client(s.User,role);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Root(s.Tenant))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Root(s.Tenant)+"/"+p.Record.Id)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Create(c,s.Tenant)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.PutAsJsonAsync(Root(s.Tenant)+"/"+p.Record.Id,new UpdateCentralPersonRequest(Guid.NewGuid(),1,Profile(),true))).StatusCode);}
 [PostgresFact]public async Task AnonymousForeignTenantWrongObjectAndIssuerCannotReadOrMutate(){var s=await Seed();using var c=Client(s.User,"MANAGER");var p=await Value(await Create(c,s.Tenant));using var anon=Client(null,"");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Root(s.Tenant))).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await Create(anon,s.Tenant)).StatusCode);
  var other=await Seed();using var foreign=Client(other.User,"MANAGER");Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync(Root(s.Tenant))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Create(foreign,s.Tenant)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync(Root(other.Tenant)+"/"+p.Record.Id)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await foreign.PutAsJsonAsync(Root(other.Tenant)+"/"+p.Record.Id,new UpdateCentralPersonRequest(Guid.NewGuid(),1,Profile(),true))).StatusCode);
  var wrongIssuer=await Seed(issuer:"https://another-issuer.invalid/realm");using var sameSub=Client(wrongIssuer.User,"MANAGER");Assert.Equal(HttpStatusCode.NotFound,(await sameSub.GetAsync(Root(wrongIssuer.Tenant))).StatusCode);using var super=Client(Guid.NewGuid().ToString(),"SUPER_ADMIN");Assert.Equal(HttpStatusCode.OK,(await super.GetAsync(Root(s.Tenant))).StatusCode);
 }
 [PostgresFact]public async Task SelfIsServerResolvedReadonlyAndMaskedWithNoOtherPersonsOrAccountMetadata(){var s=await Seed();using var manager=Client(s.User,"MANAGER");var d=await Value(await Create(manager,s.Tenant));await factory.WithDb(async db=>{db.Add(new CentralPersonAccountLink(s.Tenant,s.Account,d.Record.Id,DateTimeOffset.UtcNow));await db.SaveChangesAsync();});using var own=Client(s.User,"RESIDENT");var selfPath=$"/api/v2/tenants/{s.Tenant}/me/person";var self=(await own.GetFromJsonAsync<SelfPerson>(selfPath))!;Assert.Equal(d.Record.Id,self.Id);Assert.False(self.CanEdit);Assert.Equal("*******8901",self.MaskedIdentity);var raw=await own.GetStringAsync(selfPath);Assert.DoesNotContain("12345678901",raw);Assert.DoesNotContain(s.User,raw);Assert.DoesNotContain("fixture@example.test",raw);Assert.DoesNotContain("phoneNumber",raw);
  Assert.Equal(HttpStatusCode.BadRequest,(await own.GetAsync(selfPath+"?personId="+Guid.NewGuid())).StatusCode);Assert.Equal(HttpStatusCode.MethodNotAllowed,(await own.PutAsJsonAsync(selfPath,new{})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await manager.PutAsJsonAsync(Root(s.Tenant)+"/"+d.Record.Id,new UpdateCentralPersonRequest(Guid.NewGuid(),1,Profile(),false))).StatusCode);
  Assert.Equal(HttpStatusCode.Conflict,(await manager.PutAsJsonAsync(Root(s.Tenant)+"/"+d.Record.Id,new UpdateCentralPersonRequest(Guid.NewGuid(),1,Profile() with{Kind="LEGAL",IdentityNumber="1234567890"},true))).StatusCode);
  await factory.WithDb(async db=>{var link=await db.Set<CentralPersonAccountLink>().SingleAsync(l=>l.TenantId==s.Tenant);link.End(DateTimeOffset.UtcNow);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await own.GetAsync(selfPath)).StatusCode);
 }
 [PostgresFact]public async Task RevocationAppliesToReadsMutationAndHistoricalReplay(){var s=await Seed();using var c=Client(s.User,"MANAGER");var op=Guid.NewGuid();await Value(await Create(c,s.Tenant,op));await factory.WithDb(async db=>{(await db.Set<PersonTenantMembership>().FindAsync(s.Member))!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync(Root(s.Tenant))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Create(c,s.Tenant,op)).StatusCode);using var super=Client(Guid.NewGuid().ToString(),"SUPER_ADMIN");await factory.WithDb(async db=>{(await db.Set<PersonTenant>().FindAsync(s.Tenant))!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await super.GetAsync(Root(s.Tenant))).StatusCode);}
 [PostgresFact]public async Task LiteralSearchStablePagingAndSummaryNeverLeakIdentityOrContact(){var s=await Seed();using var c=Client(s.User,"MANAGER");for(var i=0;i<5;i++)await Value(await Create(c,s.Tenant,p:Profile(i==0?"A%_":"Fixture")));var first=(await c.GetFromJsonAsync<PagedRows<CentralPersonSummary>>(Root(s.Tenant)+"?pageSize=2&page=1"))!;var second=(await c.GetFromJsonAsync<PagedRows<CentralPersonSummary>>(Root(s.Tenant)+"?pageSize=2&page=2"))!;Assert.Equal(5,first.TotalCount);Assert.Empty(first.Items.Select(x=>x.Id).Intersect(second.Items.Select(x=>x.Id)));var literal=(await c.GetFromJsonAsync<PagedRows<CentralPersonSummary>>(Root(s.Tenant)+"?search="+Uri.EscapeDataString("%_")))!;Assert.Single(literal.Items);var contact=(await c.GetFromJsonAsync<PagedRows<CentralPersonSummary>>(Root(s.Tenant)+"?search=fixture%40example.test"))!;Assert.Equal(5,contact.TotalCount);var raw=await c.GetStringAsync(Root(s.Tenant));Assert.DoesNotContain("identityNumber",raw);Assert.DoesNotContain("phoneNumber",raw);Assert.DoesNotContain("email",raw);foreach(var q in new[]{"page=0","pageSize=101","sortBy=identityNumber","sortDirection=invalid","search="+new string('a',201)})Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Root(s.Tenant)+"?"+q)).StatusCode);}
 [PostgresFact]public async Task ValidationRejectsBadProfileDatesAndUnknownGrantFields(){var s=await Seed();using var c=Client(s.User,"MANAGER");foreach(var p in new[]{Profile() with{Kind="UNKNOWN"},Profile() with{BirthDate=new DateOnly(2999,1,1)},Profile() with{PhoneNumber="bad"},Profile() with{Email="bad"},Profile() with{FirstName="bad\nname"}})Assert.Equal(HttpStatusCode.BadRequest,(await Create(c,s.Tenant,p:p)).StatusCode);
  using var spoof=new StringContent(JsonSerializer.Serialize(new{operationId=Guid.NewGuid(),profile=Profile(),tenantId=Guid.NewGuid(),is_owner=true}),Encoding.UTF8,"application/json");Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsync(Root(s.Tenant),spoof)).StatusCode);var legal=Profile() with{Kind="LEGAL",IdentityNumber="1234567890",LastName=null};Assert.Equal("",(await Value(await Create(c,s.Tenant,p:legal))).Record.Profile.LastName);Assert.Equal(HttpStatusCode.BadRequest,(await Create(c,s.Tenant,p:legal with{BirthDate=new(1990,1,1)})).StatusCode);
 }
 [PostgresFact]public async Task LinkCompositeFkAndActiveCardinalityAreEnforcedByPostgres(){var s=await Seed();var other=await Seed();using var c=Client(s.User,"MANAGER");var p=await Value(await Create(c,s.Tenant));var q=await Value(await Create(c,s.Tenant));await factory.WithDb(async db=>{var link=new CentralPersonAccountLink(s.Tenant,s.Account,p.Record.Id,DateTimeOffset.UtcNow);db.Add(link);await db.SaveChangesAsync();var duplicate=new CentralPersonAccountLink(s.Tenant,s.Account,q.Record.Id,DateTimeOffset.UtcNow);db.Add(duplicate);await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());db.Entry(duplicate).State=EntityState.Detached;var cross=new CentralPersonAccountLink(other.Tenant,other.Account,p.Record.Id,DateTimeOffset.UtcNow);db.Add(cross);await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());db.Entry(cross).State=EntityState.Detached;});}

 [PostgresTheory][InlineData("ACCOUNT_DISABLED")][InlineData("ACCOUNT_DELETED")][InlineData("MEMBER_DELETED")][InlineData("TENANT_DELETED")]
 public async Task InactiveOrSoftDeletedScopeCannotReadSelfListOrReplay(string mode){var s=await Seed();using var c=Client(s.User,"MANAGER");var op=Guid.NewGuid();var d=await Value(await Create(c,s.Tenant,op));await factory.WithDb(async db=>{db.Add(new CentralPersonAccountLink(s.Tenant,s.Account,d.Record.Id,DateTimeOffset.UtcNow));await db.SaveChangesAsync();if(mode=="ACCOUNT_DISABLED")(await db.Set<PersonUserAccount>().FindAsync(s.Account))!.SetEnabled(false);else if(mode=="ACCOUNT_DELETED")db.Remove((await db.Set<PersonUserAccount>().FindAsync(s.Account))!);else if(mode=="MEMBER_DELETED")db.Remove((await db.Set<PersonTenantMembership>().FindAsync(s.Member))!);else db.Remove((await db.Set<PersonTenant>().FindAsync(s.Tenant))!);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync(Root(s.Tenant))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Create(c,s.Tenant,op)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync($"/api/v2/tenants/{s.Tenant}/me/person")).StatusCode);}
 [PostgresFact]public async Task FutureLinkAndSoftDeletedPersonNeverGrantSelfAccess(){var s=await Seed();using var c=Client(s.User,"MANAGER");var d=await Value(await Create(c,s.Tenant));await factory.WithDb(async db=>{db.Add(new CentralPersonAccountLink(s.Tenant,s.Account,d.Record.Id,DateTimeOffset.UtcNow.AddDays(1)));await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync($"/api/v2/tenants/{s.Tenant}/me/person")).StatusCode);await factory.WithDb(async db=>{db.Remove((await db.Set<CentralPerson>().FindAsync(d.Record.Id))!);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync(Root(s.Tenant)+"/"+d.Record.Id)).StatusCode);}
 public void Dispose()=>enabled?.Dispose();
}
